  106	// flush sends every due reminder once. It holds d.mu so flushes never
  107	// overlap.
  108	func (d *Dispatcher) flush(ctx context.Context) {
  109		d.mu.Lock()
  110		defer d.mu.Unlock()
  111		for _, r := range d.store.Due(d.now()) {
  112			u, err := d.store.User(r.UserID)
  113			if err != nil {
  114				continue
  115			}
  116			if err := d.SendNow(ctx, u, r); err != nil {
  117				d.retries[r.ID]++
  118				d.log.Warn("notify: send failed", "reminder", r.ID, "attempt", d.retries[r.ID], "err", err)
  119				continue
  120			}
  121			delete(d.retries, r.ID)
  122			d.store.MarkSent(r.ID)
  123		}
  124	}
